-- Arcanix authorization, grants, RLS and trusted state transitions.
create or replace function private.actor_is_active() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and not p.is_suspended and p.deleted_at is null); $$;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select private.actor_is_active() and exists(select 1 from public.user_roles r where r.user_id=(select auth.uid()) and r.role='admin' and r.revoked_at is null); $$;
create or replace function private.is_org_member(org uuid, roles text[]) returns boolean language sql stable security definer set search_path='' as $$ select private.actor_is_active() and exists(select 1 from public.organization_members m where m.organization_id=org and m.profile_id=(select auth.uid()) and m.status='active' and m.membership_role=any(roles)); $$;
create or replace function private.is_connected(a uuid,b uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.connections c where c.status='accepted' and ((c.requester_id=a and c.recipient_id=b) or (c.requester_id=b and c.recipient_id=a))); $$;
create or replace function private.can_view_profile(target uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.actor_is_active() and exists(select 1 from public.profiles p join public.user_settings s on s.profile_id=p.id where p.id=target and not p.is_suspended and p.deleted_at is null and (p.id=(select auth.uid()) or private.is_admin() or s.profile_visibility='public' or (s.profile_visibility='members' and (private.is_connected(p.id,(select auth.uid())) or exists(select 1 from public.organization_members x join public.organization_members y on y.organization_id=x.organization_id where x.profile_id=p.id and y.profile_id=(select auth.uid()) and x.status='active' and y.status='active'))))); $$;
create or replace function private.can_view_post(post_uuid uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.actor_is_active() and exists(select 1 from public.posts p where p.id=post_uuid and p.deleted_at is null and (p.author_id=(select auth.uid()) or private.is_admin() or p.visibility='public' or (p.visibility='connections' and private.is_connected(p.author_id,(select auth.uid()))) or (p.visibility='organization' and private.is_org_member(p.organization_id,array['owner','admin','recruiter','editor','member'])))); $$;
create or replace function private.can_manage_opportunity(opportunity_uuid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.opportunities o where o.id=opportunity_uuid and private.is_org_member(o.organization_id,array['owner','admin','recruiter'])); $$;
revoke all on all functions in schema private from public;
grant usage on schema private to authenticated;
grant execute on function private.actor_is_active(),private.is_admin(),private.is_org_member(uuid,text[]),private.is_connected(uuid,uuid),private.can_view_profile(uuid),private.can_view_post(uuid),private.can_manage_opportunity(uuid) to authenticated;

create or replace function private.assert_active_admin_remains() returns trigger language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.user_roles where role='admin' and revoked_at is null) then raise exception 'cannot remove final active administrator'; end if; return null; end; $$;
create constraint trigger user_roles_final_admin_guard after update or delete on public.user_roles deferrable initially deferred for each row execute function private.assert_active_admin_remains();
create or replace function private.assert_org_owner_remains() returns trigger language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.organization_members where organization_id=coalesce(new.organization_id,old.organization_id) and status='active' and membership_role='owner') then raise exception 'organization must retain an active owner'; end if; return null; end; $$;
create constraint trigger org_members_owner_guard after update or delete on public.organization_members deferrable initially deferred for each row execute function private.assert_org_owner_remains();

create or replace function public.transfer_organization_ownership(p_org uuid,p_target uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not(private.is_admin() or private.is_org_member(p_org,array['owner'])) then raise exception 'not authorized'; end if; perform 1 from public.organization_members where organization_id=p_org order by profile_id for update; if not exists(select 1 from public.organization_members where organization_id=p_org and profile_id=p_target and status='active') then raise exception 'target must be active member'; end if; update public.organization_members set membership_role='owner' where organization_id=p_org and profile_id=p_target; update public.organization_members set membership_role='admin' where organization_id=p_org and profile_id=(select auth.uid()) and profile_id<>p_target and membership_role='owner'; insert into public.admin_actions(actor_id,action_type,target_organization_id,metadata) values(auth.uid(),'organization_ownership_transferred',p_org,jsonb_build_object('target',p_target)); end; $$;
create or replace function public.set_application_status(p_application uuid,p_status text,p_note text default null) returns void language plpgsql security definer set search_path='' as $$ declare v_old text; begin select status into v_old from public.applications where id=p_application for update; if not found or not private.can_manage_opportunity((select opportunity_id from public.applications where id=p_application)) then raise exception 'not authorized'; end if; if p_status not in ('under_review','interview','offered','rejected') then raise exception 'invalid status'; end if; update public.applications set status=p_status where id=p_application; insert into public.application_reviews(application_id,reviewer_id,from_status,to_status,internal_note) values(p_application,auth.uid(),v_old,p_status,p_note); end; $$;
create or replace function public.withdraw_application(p_application uuid) returns void language plpgsql security definer set search_path='' as $$ begin update public.applications set status='withdrawn',withdrawn_at=now() where id=p_application and applicant_id=auth.uid() and status='submitted'; if not found then raise exception 'cannot withdraw application'; end if; end; $$;
create or replace function public.update_application_cover_note(p_application uuid,p_cover_note text) returns void language plpgsql security definer set search_path='' as $$ begin update public.applications set cover_note=p_cover_note where id=p_application and applicant_id=auth.uid() and status='submitted'; if not found then raise exception 'cannot update application'; end if; end; $$;
revoke all on function public.transfer_organization_ownership(uuid,uuid),public.set_application_status(uuid,text,text),public.withdraw_application(uuid),public.update_application_cover_note(uuid,text) from public;
grant execute on function public.transfer_organization_ownership(uuid,uuid),public.set_application_status(uuid,text,text),public.withdraw_application(uuid),public.update_application_cover_note(uuid,text) to authenticated;

do $$ declare t text; begin foreach t in array array['games','profiles','user_roles','user_settings','organizations','organization_members','player_details','player_skills','player_achievements','player_experience','profile_media','verification_requests','verification_history','verification_review_notes','verification_documents','posts','post_media','likes','comments','follows','connections','connection_events','saved_posts','opportunities','applications','application_reviews','notifications','reports','report_reviews','admin_actions'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); end loop; end $$;
grant select on public.games to authenticated;
grant select on public.profiles,public.user_settings,public.player_details,public.player_skills,public.player_achievements,public.player_experience,public.profile_media to authenticated;
grant update(handle,display_name,headline,bio,city,country_code,is_discoverable) on public.profiles to authenticated;
grant update(profile_visibility,allow_messages,notify_email,notify_push,locale) on public.user_settings to authenticated;
grant select,insert,update,delete on public.player_details,public.player_skills,public.player_achievements,public.player_experience,public.profile_media to authenticated;
grant select,insert,update,delete on public.posts,public.post_media,public.likes,public.comments,public.follows,public.connections,public.saved_posts to authenticated;
grant select,insert,update,delete on public.organizations,public.organization_members,public.opportunities,public.reports to authenticated;
grant select,insert on public.applications to authenticated;
grant select,update(read_at) on public.notifications to authenticated;

create policy games_read on public.games for select to authenticated using(is_active);
create policy profiles_read on public.profiles for select to authenticated using(private.can_view_profile(id));
create policy profiles_update_self on public.profiles for update to authenticated using(id=auth.uid() and private.actor_is_active()) with check(id=auth.uid() and private.actor_is_active());
create policy settings_owner on public.user_settings for select to authenticated using(profile_id=auth.uid());
create policy settings_update_owner on public.user_settings for update to authenticated using(profile_id=auth.uid() and private.actor_is_active()) with check(profile_id=auth.uid());
create policy player_details_read on public.player_details for select to authenticated using(private.can_view_profile(profile_id));
create policy player_details_owner on public.player_details for all to authenticated using(profile_id=auth.uid() and private.actor_is_active()) with check(profile_id=auth.uid() and private.actor_is_active());
create policy player_skills_read on public.player_skills for select to authenticated using(private.can_view_profile(profile_id));
create policy player_skills_owner on public.player_skills for all to authenticated using(profile_id=auth.uid() and private.actor_is_active()) with check(profile_id=auth.uid() and private.actor_is_active());
create policy player_achievements_read on public.player_achievements for select to authenticated using(private.can_view_profile(profile_id));
create policy player_achievements_owner on public.player_achievements for all to authenticated using(profile_id=auth.uid() and private.actor_is_active()) with check(profile_id=auth.uid() and private.actor_is_active());
create policy player_experience_read on public.player_experience for select to authenticated using(private.can_view_profile(profile_id));
create policy player_experience_owner on public.player_experience for all to authenticated using(profile_id=auth.uid() and private.actor_is_active()) with check(profile_id=auth.uid() and private.actor_is_active());
create policy profile_media_read on public.profile_media for select to authenticated using(private.can_view_profile(profile_id));
create policy profile_media_owner on public.profile_media for all to authenticated using(profile_id=auth.uid() and private.actor_is_active()) with check(profile_id=auth.uid() and private.actor_is_active() and storage_path like auth.uid()::text||'/%');
create policy org_read on public.organizations for select to authenticated using(is_active or private.is_org_member(id,array['owner','admin','recruiter','editor','member']) or private.is_admin());
create policy org_create on public.organizations for insert to authenticated with check(created_by=auth.uid() and private.actor_is_active());
create policy org_update on public.organizations for update to authenticated using(private.is_org_member(id,array['owner','admin']) or private.is_admin()) with check(private.is_org_member(id,array['owner','admin']) or private.is_admin());
create policy org_members_read on public.organization_members for select to authenticated using(profile_id=auth.uid() or private.is_org_member(organization_id,array['owner','admin','recruiter','editor','member']) or private.is_admin());
create policy posts_read on public.posts for select to authenticated using(private.can_view_post(id));
create policy posts_owner on public.posts for insert to authenticated with check(author_id=auth.uid() and private.actor_is_active() and (organization_id is null or private.is_org_member(organization_id,array['owner','admin','recruiter','editor'])));
create policy posts_update_owner on public.posts for update to authenticated using(author_id=auth.uid() and private.actor_is_active()) with check(author_id=auth.uid() and (organization_id is null or private.is_org_member(organization_id,array['owner','admin','recruiter','editor'])));
create policy posts_delete_owner on public.posts for delete to authenticated using(author_id=auth.uid() and private.actor_is_active());
create policy post_media_read on public.post_media for select to authenticated using(private.can_view_post(post_id));
create policy post_media_owner on public.post_media for all to authenticated using(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid()) and private.actor_is_active()) with check(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid()) and storage_path like auth.uid()::text||'/%');
create policy likes_read on public.likes for select to authenticated using(private.can_view_post(post_id));
create policy likes_owner on public.likes for insert to authenticated with check(profile_id=auth.uid() and private.can_view_post(post_id));
create policy likes_delete_owner on public.likes for delete to authenticated using(profile_id=auth.uid());
create policy comments_read on public.comments for select to authenticated using(private.can_view_post(post_id));
create policy comments_owner on public.comments for all to authenticated using(author_id=auth.uid() and private.actor_is_active()) with check(author_id=auth.uid() and private.can_view_post(post_id));
create policy follows_owner on public.follows for all to authenticated using(follower_id=auth.uid() and private.actor_is_active()) with check(follower_id=auth.uid() and follower_id<>followed_id and private.can_view_profile(followed_id));
create policy connections_participants on public.connections for select to authenticated using(requester_id=auth.uid() or recipient_id=auth.uid() or private.is_admin());
create policy connections_request on public.connections for insert to authenticated with check(requester_id=auth.uid() and private.actor_is_active() and requester_id<>recipient_id);
create policy connections_recipient_update on public.connections for update to authenticated using(recipient_id=auth.uid() or requester_id=auth.uid()) with check(recipient_id=auth.uid() or requester_id=auth.uid());
create policy saved_owner on public.saved_posts for all to authenticated using(profile_id=auth.uid()) with check(profile_id=auth.uid() and private.can_view_post(post_id));
create policy opportunities_read on public.opportunities for select to authenticated using(status='published' or private.is_org_member(organization_id,array['owner','admin','recruiter','editor','member']) or private.is_admin());
create policy opportunities_create on public.opportunities for insert to authenticated with check(private.is_org_member(organization_id,array['owner','admin','recruiter']) and created_by=auth.uid());
create policy opportunities_update on public.opportunities for update to authenticated using(private.can_manage_opportunity(id)) with check(private.is_org_member(organization_id,array['owner','admin','recruiter']));
create policy opportunities_delete on public.opportunities for delete to authenticated using(private.can_manage_opportunity(id));
create policy applications_read on public.applications for select to authenticated using(applicant_id=auth.uid() or private.can_manage_opportunity(opportunity_id) or private.is_admin());
create policy applications_create on public.applications for insert to authenticated with check(applicant_id=auth.uid() and private.actor_is_active() and exists(select 1 from public.opportunities o where o.id=opportunity_id and o.status='published'));
create policy notifications_read on public.notifications for select to authenticated using(recipient_id=auth.uid());
create policy notifications_mark_read on public.notifications for update to authenticated using(recipient_id=auth.uid()) with check(recipient_id=auth.uid());
create policy reports_read on public.reports for select to authenticated using(reporter_id=auth.uid() or private.is_admin());
create policy reports_create on public.reports for insert to authenticated with check(reporter_id=auth.uid() and private.actor_is_active());
create policy reports_owner_delete on public.reports for delete to authenticated using(reporter_id=auth.uid() and status='open');
